.editor-loading {
  display: flex;
  min-height: 100svh;
  flex-direction: column;
  background: var(--color-paper);
  color: var(--color-ink);
}

.editor-loading__masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0 2rem;
  padding: 1.25rem 0;
  border-bottom: 1px solid var(--color-rule);
}

.editor-loading__wordmark {
  font: 700 1.5rem/1 var(--font-display);
  letter-spacing: -0.04em;
}

.editor-loading__wordmark > span {
  color: var(--color-vermilion);
}

.editor-loading__department {
  color: var(--color-ink-light);
  font: 400 0.8125rem/1.5 var(--font-serif);
  font-style: italic;
}

.editor-loading__desk {
  display: grid;
  flex: 1;
  place-items: center;
  padding: 2.5rem 1.5rem 4rem;
}

.editor-loading__page {
  width: min(100%, 37rem);
  padding: 1.5rem 3.5rem 1.25rem;
  background: var(--color-editor-bg);
  border: 1px solid var(--color-rule);
  /* A crisp second sheet, with no blurred card shadow. */
  box-shadow:
    4px 4px 0 var(--color-paper),
    5px 5px 0 var(--color-rule);
}

.editor-loading__page-head,
.editor-loading__page-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  color: var(--color-ink-light);
  font: 400 0.75rem/1.5 var(--font-typewriter);
}

.editor-loading__page-head {
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-rule);
}

.editor-loading__registration {
  font: 400 1.125rem/1 var(--font-mono);
}

.editor-loading__status {
  margin: 2.75rem 0 2.5rem;
}

.editor-loading__status h1 {
  margin: 0;
  max-width: 17ch;
  font: 400 1.75rem/1.4 var(--font-display);
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.editor-loading__status p {
  margin: 0.75rem 0 0;
  color: var(--color-ink-light);
  font: 400 0.875rem/1.6 var(--font-sans);
}

.editor-loading__proof {
  position: relative;
  padding-bottom: 2rem;
}

.editor-loading__paragraph {
  display: grid;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

.editor-loading__line {
  display: block;
  height: 0.375rem;
  width: 100%;
  background: color-mix(in srgb, var(--color-ink) 10%, var(--color-editor-bg));
}

.editor-loading__line--title {
  width: 36%;
  height: 0.625rem;
}

.editor-loading__line--short {
  width: 62%;
}

.editor-loading__line--medium {
  width: 81%;
}

.editor-loading__caret {
  display: block;
  width: 2px;
  height: 1rem;
  margin-top: 1rem;
  background: var(--color-vermilion);
}

.editor-loading__page-foot {
  justify-content: flex-start;
  padding-top: 1rem;
  border-top: 1px solid var(--color-rule);
}

.editor-loading__activity {
  width: 2rem;
  height: 2px;
  overflow: hidden;
  background: var(--color-rule);
}

.editor-loading__activity > span {
  display: block;
  width: 50%;
  height: 100%;
  background: var(--color-vermilion);
}

@media (prefers-reduced-motion: no-preference) {
  .editor-loading__activity > span {
    animation: editor-loading-ink 1.8s ease-in-out infinite alternate;
  }

  .editor-loading__caret {
    animation: editor-loading-caret 1.8s ease-in-out infinite;
  }
}

@keyframes editor-loading-ink {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(100%);
  }
}

@keyframes editor-loading-caret {
  0%,
  100% {
    opacity: 0.35;
  }
  50% {
    opacity: 1;
  }
}

@media (max-width: 480px) {
  .editor-loading__masthead {
    margin-inline: 1.25rem;
    padding-block: 1rem;
  }

  .editor-loading__desk {
    padding: 1.5rem 1.25rem 2rem;
  }

  .editor-loading__page {
    padding: 1.25rem 1.5rem;
  }

  .editor-loading__status {
    margin-block: 2rem;
  }

  .editor-loading__status h1 {
    font-size: 1.5rem;
  }
}
