          "Link your Not Organic account before using hosted narration.",
        );
      const token = await issueNotOrganicAccessToken({
        ...link,
        feature: "voice-narration",
        capabilities: [`infer:${HOSTED_SPEECH_MODEL}`],
      });
      const route = notOrganicOpenAiRoute(
        token,
        HOSTED_SPEECH_MODEL,
        "voice-narration",
        notOrganicIssuer(),
      );
      // The gateway authorizes and settles the linked account's credit. A
      // gateway rejection must never spend against the legacy OpenAI key.
      const voice = resolveHostedSpeechVoice(args.voice);
      const res = await route.fetch(`${route.baseURL}/audio/speech`, {
        method: "POST",
        headers: {
          ...route.headers,
          authorization: `Bearer ${route.apiKey}`,
          "content-type": "application/json",
        },
        signal: AbortSignal.timeout(150_000),
        body: JSON.stringify({
          model: route.model,
          input,
          voice,
          response_format: responseFormat,
          stream: false,
          timestamps: true,
          include_timestamps: true,
          // ElevenLabs accepts audio tags in the input, not OpenAI's freeform
          // instructions or speed parameters. Never read those directions aloud.
          voice_settings: { stability: 0.5, similarity_boost: 0.75 },
        }),
      });
      if (!res.ok) {
        // Retain HTTP evidence and a support reference, never raw upstream
        // bodies (which can echo manuscript text or credentials).
        const code: ApplicationErrorCode =
          res.status === 401
            ? "authentication_required"
            : res.status === 402 || res.status === 403
              ? "permission_denied"
              : res.status === 400 || res.status === 404
                ? "configuration_required"
                : res.status === 429
                  ? "rate_limited"
                  : "provider_unavailable";
        throw reportedApplicationError(
          "voice.synthesize",
          code,
          new Error(`Hosted narration HTTP ${res.status}`),
          {
            message:
              res.status === 402
                ? "Add Not Organic wallet credit to use hosted narration."
                : res.status === 400 || res.status === 404
                  ? "The hosted voice route is unavailable. Please contact support with this reference."
                  : "Hosted narration could not finish. Please try again later.",
            retryable: res.status === 429 || res.status >= 500,
          },
          {
            status: res.status,
            provider: "notorganic",
            model: route.model,
            operation: "speech",
          },
        );
      }
      const rawBytes = await res.arrayBuffer();
      let contentType = res.headers
        .get("content-type")
        ?.split(";")[0]
        .trim()
        .toLowerCase();
      let payload: Record<string, unknown> | undefined;
      if (contentType === "application/json") {
        try {
          const parsed: unknown = JSON.parse(
            Buffer.from(rawBytes).toString("utf8"),
          );
          if (parsed && typeof parsed === "object" && !Array.isArray(parsed))
            payload = parsed as Record<string, unknown>;
        } catch {
          /* Invalid envelopes are rejected below without leaking their contents. */
        }
      }
      const bytes =
        payload &&
        typeof payload.audio_base64 === "string" &&
        /^[A-Za-z0-9+/]+={0,2}$/.test(payload.audio_base64)
          ? Buffer.from(payload.audio_base64, "base64")
          : contentType === "application/json"
            ? new Uint8Array(0)
            : new Uint8Array(rawBytes);
      if (payload && typeof payload.content_type === "string") {
        contentType = payload.content_type.split(";")[0].trim().toLowerCase();
      }
      if (
        !bytes.byteLength ||
        (contentType &&
          !contentType.startsWith("audio/") &&
          contentType !== "application/octet-stream")
      ) {
        throw reportedApplicationError(
          "voice.synthesize",
          "malformed_response",
          new Error("Hosted narration returned no playable audio"),
          {},
          {
            status: res.status,
            provider: "notorganic",
            model: route.model,
            operation: "speech",
          },
        );
      }
      return {
        audioBase64: Buffer.from(bytes).toString("base64"),
        mimeType: contentType?.startsWith("audio/")
          ? contentType
          : responseFormat === "opus"
            ? "audio/ogg"
            : responseFormat === "pcm"
              ? "audio/pcm"
              : "audio/mpeg",
        responseFormat,
        provider: "notorganic",
        model: route.model,
        voice,
        alignment: {
          provider: "elevenlabs",
          ranges: mapElevenLabsTimestamps(input, payload?.timestamps),
        },
      };
    }

    throw new Error("Hosted ElevenLabs narration is not configured.");
  },
});

/** Roughly three minutes of Opus at 32kbps, base64-encoded. */
const MAX_TRANSCRIBE_BYTES = 12 * 1024 * 1024;

/**
 * Transcribe a recorded voice note.
 *
 * Uses the identity check and rate limiter, with its legacy Pro gate and
 * transcription key. The audio arrives base64-encoded
 * because Convex actions take JSON — the client keeps the original Blob locally,
 * so nothing is lost by re-encoding for the wire.
 */
export const transcribeSpeech = action({
  args: {
    audioBase64: v.string(),
    mimeType: v.string(),
    /** Optional nudge for proper nouns and jargon the recording will contain. */
    prompt: v.optional(v.string()),
    model: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");

    await consumeRateLimit(ctx, {
      action: "voice:transcribe",
      identifier: identity.tokenIdentifier,
      ...RATE_LIMITS.voiceTranscribe,
    });

    if (!(await userIsPro(ctx, identity.subject || identity.tokenIdentifier))) {
      throw new Error("Hosted transcription is a Pro feature.");
    }

    const apiKey =REDACTED      process.env.VOICE_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("Hosted transcription is not configured.");

    const bytes = Buffer.from(args.audioBase64, "base64");
    if (bytes.length === 0) throw new Error("Nothing to transcribe.");
    if (bytes.length > MAX_TRANSCRIBE_BYTES) {
      throw new Error("That recording is too long to transcribe.");
    }

    const model =
      args.model ??
      process.env.VOICE_OPENAI_TRANSCRIBE_MODEL ??
      "gpt-4o-mini-transcribe";

    const form = new FormData();
    form.append(
      "file",
      new Blob([new Uint8Array(bytes)], { type: args.mimeType }),
      `note.${extensionForMime(args.mimeType)}`,
    );
    form.append("model", model);
    form.append("response_format", "json");
    if (args.prompt?.trim())
      form.append("prompt", args.prompt.trim().slice(0, 800));

    const res = await fetch(`${OPENAI_AUDIO_BASE}/audio/transcriptions`, {
      method: "POST",
      headers: { authorization: `Bearer ${apiKey}` },
      body: form,
    });

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Hosted transcription failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }

    const data = (await res.json()) as { text?: string };
    return {
      text: typeof data.text === "string" ? data.text.trim() : "",
      provider: "openai",
      model,
    };
  },
});

/** The file extension the transcription endpoint expects for a MIME type. */
function extensionForMime(mimeType: string): string {
  const base = mimeType.split(";")[0].trim().toLowerCase();
  switch (base) {
    case "audio/webm":
      return "webm";
    case "audio/ogg":
      return "ogg";
    case "audio/mp4":
    case "audio/m4a":
      return "m4a";
    case "audio/wav":
    case "audio/x-wav":
      return "wav";
    case "audio/mpeg":
      return "mp3";
    default:
      return "webm";
  }
}
