    alignment: v.optional(
      v.object({
        provider: v.string(),
        ranges: v.array(
          v.object({
            sourceStart: v.number(),
            sourceEnd: v.number(),
            audioStart: v.number(),
            audioEnd: v.number(),
            precision: v.union(v.literal("word"), v.literal("segment")),
