        throw reportedApplicationError(
          "voice.synthesize",
          "malformed_response",
          new Error("Hosted narration returned no playable audio"),
          {},
          {
            status: res.status,
            provider: "notorganic",
            model: route.model,
            operation: "speech",
          },
        );
      }
