import {
  $,
  component$,
  useSignal,
  useVisibleTask$,
  type PropFunction,
} from "@qwik.dev/core";

export interface SiteSelectOption {
  value: string;
  label: string;
  description?: string;
}

interface SiteSelectProps {
  value: string;
  options: SiteSelectOption[];
  onChange$: PropFunction<(value: string) => void>;
  ariaLabel: string;
  disabled?: boolean;
  class?: string;
}

/** A paper-and-ink listbox whose opened options can follow Twyne's design. */
export const SiteSelect = component$<SiteSelectProps>((props) => {
  const root = useSignal<HTMLElement>();
  const trigger = useSignal<HTMLButtonElement>();
  const open = useSignal(false);
  const activeIndex = useSignal(0);
  const selectedIndex = Math.max(
    0,
    props.options.findIndex((option) => option.value === props.value),
  );
  const selected = props.options[selectedIndex] ?? props.options[0];

  const close = $((returnFocus = false) => {
    open.value = false;
    if (returnFocus) trigger.value?.focus();
  });

  const choose = $((index: number) => {
    const option = props.options[index];
    if (!option) return;
    props.onChange$(option.value);
    void close(true);
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const onPointerDown = (event: PointerEvent) => {
      if (!root.value?.contains(event.target as Node)) void close();
    };
    document.addEventListener("pointerdown", onPointerDown);
    cleanup(() => document.removeEventListener("pointerdown", onPointerDown));
  });

  return (
    <div
      ref={root}
      class={`site-select${props.class ? ` ${props.class}` : ""}`}
    >
      <button
        ref={trigger}
        type="button"
        class="site-select__trigger"
        aria-label={props.ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open.value}
        disabled={props.disabled || props.options.length === 0}
        onClick$={() => {
          activeIndex.value = selectedIndex;
          open.value = !open.value;
        }}
        onKeyDown$={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            const delta = event.key === "ArrowDown" ? 1 : -1;
            activeIndex.value = open.value
              ? (activeIndex.value + delta + props.options.length) %
                props.options.length
              : selectedIndex;
            open.value = true;
          } else if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            if (open.value) void choose(activeIndex.value);
            else open.value = true;
          } else if (event.key === "Escape") {
            event.preventDefault();
            void close();
          }
        }}
      >
        <span class="site-select__value">{selected?.label ?? "Choose"}</span>
        <span class="site-select__chevron" aria-hidden="true">
          ⌄
        </span>
      </button>

      {open.value && (
        <div
          class="site-select__menu"
          role="listbox"
          aria-label={props.ariaLabel}
          tabIndex={-1}
          onKeyDown$={(event) => {
            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
              event.preventDefault();
              const delta = event.key === "ArrowDown" ? 1 : -1;
              activeIndex.value =
                (activeIndex.value + delta + props.options.length) %
                props.options.length;
            } else if (event.key === "Home") {
              event.preventDefault();
              activeIndex.value = 0;
            } else if (event.key === "End") {
              event.preventDefault();
              activeIndex.value = props.options.length - 1;
            } else if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              void choose(activeIndex.value);
            } else if (event.key === "Escape" || event.key === "Tab") {
              void close(event.key === "Escape");
            }
          }}
        >
          {props.options.map((option, index) => {
            const isSelected = option.value === props.value;
            const isActive = index === activeIndex.value;
            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={isSelected}
                class={`site-select__option${
                  isActive ? " is-active" : ""
                }${isSelected ? " is-selected" : ""}`}
                onPointerMove$={() => {
                  activeIndex.value = index;
                }}
                onClick$={() => choose(index)}
              >
                <span class="site-select__check" aria-hidden="true">
                  {isSelected ? "✓" : ""}
                </span>
                <span class="site-select__option-copy">
                  <span>{option.label}</span>
                  {option.description && <small>{option.description}</small>}
                </span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
});

import { component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { SpeechErrorPanel } from "./speech-error-panel";
import { useSpeechPlayer } from "../../utils/use-speech-player";
import { openLiveVoice } from "../../utils/live-voice-workspace";
import {
  currentSpeechSourceOffset,
  currentSpeechText,
  resumeSpeech,
  seekSpeech,
  speechState,
} from "../../utils/speech";
import {
  buildSpeechTimeline,
  type SpeechTimeline,
} from "../../utils/speech-follow-along";
import { alignmentRangeAtTime } from "../../utils/speech-alignment";
import {
  buildSpeechSourceMap,
  mapSpeechSourceRange,
  type SpeechSourceMap,
} from "../../utils/speech-source-map";

const SENTENCE_HIGHLIGHT = "twyne-speech-sentence";
const WORD_HIGHLIGHT = "twyne-speech-word";

interface SpeechTextSlice {
  node: Text;
  start: number;
  end: number;
}

interface SpeechTextMap {
  root: HTMLElement;
  text: string;
  slices: SpeechTextSlice[];
  timeline: SpeechTimeline;
  sourceMap: SpeechSourceMap | null;
  sourceText: string | null;
  sourceOffset: number | null;
  /** Location of the exact clip text inside the rendered target. */
  spokenStart: number;
  spokenEnd: number;
}

interface HighlightRegistryLike {
  set(name: string, highlight: unknown): void;
  delete(name: string): void;
}

type HighlightConstructor = new (...ranges: Range[]) => unknown;

function speechHighlightApi(): {
  registry: HighlightRegistryLike;
  Highlight: HighlightConstructor;
} | null {
  const registry = (CSS as unknown as { highlights?: HighlightRegistryLike })
    .highlights;
  const Highlight = (window as unknown as { Highlight?: HighlightConstructor })
    .Highlight;
  return registry && Highlight ? { registry, Highlight } : null;
}

function clearSpeechHighlights(): void {
  const api = speechHighlightApi();
  api?.registry.delete(WORD_HIGHLIGHT);
  api?.registry.delete(SENTENCE_HIGHLIGHT);
}

function buildSpeechTextMap(root: HTMLElement): SpeechTextMap {
  const slices: SpeechTextSlice[] = [];
  const parts: string[] = [];
  let length = 0;
  let previousBlock: Element | null = null;
  const blockTags = new Set([
    "ADDRESS",
    "ARTICLE",
    "ASIDE",
    "BLOCKQUOTE",
    "DIV",
    "FIGCAPTION",
    "H1",
    "H2",
    "H3",
    "H4",
    "H5",
    "H6",
    "LI",
    "P",
    "PRE",
    "SECTION",
  ]);
  const nearestBlock = (textNode: Text): Element => {
    let element: Element | null = textNode.parentElement;
    while (element && element !== root) {
      if (blockTags.has(element.tagName)) return element;
      element = element.parentElement;
    }
    return root;
  };
  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
    {
      acceptNode(node) {
        const parent = node.parentElement;
        if (
          !parent ||
          parent.closest(
            'button, input, select, textarea, script, style, [aria-hidden="true"], [data-speech-ignore]',
          )
        ) {
          return NodeFilter.FILTER_REJECT;
        }
        if (node instanceof Element)
          return node.tagName === "BR"
            ? NodeFilter.FILTER_ACCEPT
            : NodeFilter.FILTER_SKIP;
        if (
          !(node as Text).data.trim() &&
          ((parent === root && root.children.length) ||
            ["UL", "OL", "TABLE", "THEAD", "TBODY", "TR"].includes(
              parent.tagName,
            ))
        ) {
          return NodeFilter.FILTER_REJECT;
        }
        return node.textContent?.length
          ? NodeFilter.FILTER_ACCEPT
          : NodeFilter.FILTER_REJECT;
      },
    },
  );

  let node = walker.nextNode();
  while (node) {
    if (node instanceof Element) {
      parts.push("\n");
      length += 1;
      node = walker.nextNode();
      continue;
    }
    const textNode = node as Text;
    const value = textNode.data;
    const block = nearestBlock(textNode);
    if (
      previousBlock &&
      block !== previousBlock &&
      !block.contains(previousBlock) &&
      !previousBlock.contains(block)
    ) {
      parts.push("\n\n");
      length += 2;
    }
    slices.push({ node: textNode, start: length, end: length + value.length });
    parts.push(value);
    length += value.length;
    previousBlock = block;
    node = walker.nextNode();
  }

