  /networkerror/i,
  /load failed/i,
  /connection (?:refused|reset|closed)/i,
  /\bECONN(?:REFUSED|RESET|ABORTED)\b/i,
  /\bENOTFOUND\b/i,
  /\bEAI_AGAIN\b/i,
  /socket hang up/i,
  /offline/i,
];

const TIMEOUT_PATTERNS = [
  /timed?\s*out/i,
  /\btimeout\b/i,
  /deadline exceeded/i,
  /aborterror/i,
  /the operation was aborted/i,
];

const MALFORMED_PATTERNS = [
  /invalid json/i,
  /unexpected (?:token|end of json)/i,
  /json parse/i,
