    ...options,
    source: "provider",
    status: options.status ?? status,
    recovery: {
      ...options.recovery,
      ...(retryAfterMs === undefined ? {} : { retryAfterMs }),
    },
    validationKey:
      options.validationKey ?? validationKeyFromMessage(rawMessage),
    metadata: {
      ...pickSafeMetadata(record),
      ...pickSafeMetadata(body),
      ...options.metadata,
    },
  });
