#!/usr/bin/env python3
"""Bounded, allowlisted incident evidence. Python standard library only."""
import argparse
from collections import Counter, defaultdict, deque
import datetime as dt
import hashlib
import json
import re
from pathlib import Path

UUID = r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
REF = re.compile(r"(?<![a-z0-9])(?:err_)?(" + UUID + r")(?![a-z0-9])", re.I)
SAFE_ID = re.compile(r"(?:" + UUID + r"|[a-f0-9]{8,64}|(?:twyne_|route_)[a-f0-9]{64})\Z", re.I)
SENSITIVE = re.compile(r"bearer\s|dpop\s|\b(?:sk[-_]|pk_live_|sk_live_|eyJ[A-Za-z0-9_-]{12}|gh[pousr]_|github_pat_|AKIA|ASIA|xox[baprs]-|GOCSPX-)|[\w.+-]+@[\w.-]+\.[a-z]{2,}|(?<!\d)\d{3}-\d{2}-\d{4}(?!\d)", re.I)
PRIVATE_KEYS = re.compile(r"prompt|document|body|input|output|content|authorization|token|cookie|password|secret|api.?key|email|did|subject", re.I)
DUMP_MARKER = re.compile(r"\b(?:prompt|(?:request|response|document)[ _-]+body|document|body|input|output|content|authorization|api[_ -]?key|password|cookie|token|secret)[\"']?\s*[:=]", re.I)
TIME_KEYS = ("timestamp", "executionTimestamp", "execution_timestamp", "time", "createdAt", "_creationTime")
ID_KEYS = ("reference", "errorId", "error_id", "incidentId", "incident_ref", "requestId", "request_id", "traceId", "trace_id", "correlationId", "idempotencyKey", "idempotency_key")
META_KEYS = TIME_KEYS + ID_KEYS + ("app", "product", "service", "serviceId", "deploymentId", "functionName")
WRAPPERS = ("structuredContent", "deploy", "build", "http", "logs", "logLines", "events", "entries", "data", "records")
UTC = dt.timezone.utc


def timestamp(value):
    try:
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            # Exports use seconds or milliseconds; reject ambiguous nanoseconds.
            seconds = value / 1000 if abs(value) >= 1e11 else value
            if abs(seconds) >= 1e11:
                return None
            return dt.datetime.fromtimestamp(seconds, UTC)
        if not isinstance(value, str):
            return None
        parsed = dt.datetime.fromisoformat(value.strip().replace(" UTC", "+00:00").replace("Z", "+00:00"))
        return parsed.astimezone(UTC) if parsed.tzinfo else None
    except (ValueError, OverflowError, OSError):
        return None


def utc_arg(value):
    parsed = timestamp(value)
    try:
        original = dt.datetime.fromisoformat(value.replace(" UTC", "+00:00").replace("Z", "+00:00"))
    except ValueError:
        original = None
    if parsed is None or original is None or original.utcoffset() != dt.timedelta(0):
        raise argparse.ArgumentTypeError("Use an explicit UTC timestamp ending in Z or +00:00.")
    return parsed


def normalize_ref(value):
    match = re.fullmatch(r"(?:err_)?(" + UUID + r")", value, re.I)
    if not match:
        raise argparse.ArgumentTypeError("Incident reference must be a UUID or err_UUID.")
    return match[1].lower()


def identifier(value):
    if not isinstance(value, str) or SENSITIVE.search(value):
        return None
    value = re.sub(r"^err_", "", value, flags=re.I).lower()
    return value if SAFE_ID.fullmatch(value) else None


def safe_label(value, maxlen=128):
    if not isinstance(value, str) or SENSITIVE.search(value) or PRIVATE_KEYS.search(value):
        return None
    return value if re.fullmatch(r"[a-zA-Z0-9_:@./+-]{1," + str(maxlen) + r"}", value) else None


def scope_arg(value):
    label = safe_label(value)
    if label is None or value.startswith("-"):
        raise argparse.ArgumentTypeError("Use an app/service identifier, not a URL, credential or personal name.")
    return label


def integer(value):
    return value if isinstance(value, int) and not isinstance(value, bool) and 0 <= value <= 10**15 else None


def scope_fingerprint(value):
    # Compare declared scope before redaction; never emit the original value.
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest() if value is not None else None


def event_from(record, source, pointer, inherited=None, notes=None):
    record = {**(inherited or {}), **record}
    text = record.get("message", record.get("error", ""))
    if isinstance(text, dict):
        text = text.get("message", "")
    if not isinstance(text, str):
        text = ""
    # Never mine logged prompts, document bodies or credentials for correlation IDs.
    if len(text.encode("utf-8")) > 65536:
        if notes is not None:
            notes["oversizedLines"] += 1
        text = ""
    if DUMP_MARKER.search(text.replace('\\"', '"').replace("\\'", "'")):
        text = ""
    ids = {x for k in ID_KEYS if (x := identifier(record.get(k))) is not None}
    ids.update(m.group(1).lower() for m in REF.finditer(text))
    for match in re.finditer(r"(?:request(?:\s+id)?|trace(?:\s+id)?)\s*[:=]\s*([a-f0-9]{8,64})\b", text, re.I):
        ids.add(match.group(1).lower())
    when = next((parsed for k in TIME_KEYS if (parsed := timestamp(record.get(k))) is not None), None)
    if when is None:
        match = re.search(r"\b\d{4}-\d\d-\d\d[T ]\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d| UTC)", text)
        when = timestamp(match.group(0)) if match else None
    error = record.get("error") if isinstance(record.get("error"), dict) else {}
    code = safe_label(record.get("errorCode", record.get("error_code", error.get("code"))), 80)
    low = (text + " " + (code or "")).lower()
    status = record.get("httpStatus", record.get("status"))
    status = status if isinstance(status, int) and 100 <= status <= 599 else None
    upstream = record.get("upstreamStatus", record.get("upstream_status"))
    upstream = upstream if isinstance(upstream, int) and 100 <= upstream <= 599 else None
    m = re.search(r"upstream_http_(\d{3})", low)
    if m:
        upstream = int(m.group(1))
    state = record.get("state", record.get("reservationState", record.get("status")))
    states = ("reserved", "released", "settled", "charged", "pending", "failed", "cancelled", "canceled")
    state = state if isinstance(state, str) and state in states else None
    stage = record.get("stage")
    permitted = {"client_relay", "hosted_action", "auth", "metering_headers", "reservation", "routing", "upstream", "settlement", "local_runtime_fallback"}
    stage = stage if isinstance(stage, str) and stage in permitted else None
    if re.search(r"wasm|webassembly", low) and re.search(r"missing|fallback|not found|failed", low):
        stage = "local_runtime_fallback"
    elif re.search(r"idempotency.*(?:missing|required)|missing.*idempotency|max.cost.*(?:missing|required)|missing.*max.cost|invalid_max_cost", low):
        stage = "metering_headers"
    elif upstream is not None:
        stage = "upstream"
    elif status in (401, 403) or re.search(r"invalid_authorization|unauthorized|invalid_dpop|expired.token", low):
        stage = "auth"
    elif re.search(r"model_unavailable|model_endpoint_unavailable|route_unavailable", low):
        stage = "routing"
    elif state in ("reserved", "released") or re.search(r"insufficient.funds|insufficient.credits", low):
        stage = "reservation"
    elif record.get("billedMicros") is not None or state in ("settled", "charged"):
        stage = "settlement"
    elif record.get("functionName") or re.search(r"\[convex [aqm]\(|conven[e]?room", low):
        stage = stage or "hosted_action"
    elif "reference" in low and ids:
        stage = stage or "client_relay"
    if not (ids or stage or status or upstream):
        return None
    result = {"source": source, "record": pointer, "identifiers": sorted(ids), "stage": stage or "unknown"}
    for key, value in {"_appScope": record.get("app", record.get("product")), "_serviceScope": record.get("service", record.get("serviceId"))}.items():
        if value is not None:
            result[key] = scope_fingerprint(value)
    if stage == "metering_headers":
        issues = []
        if "idempotency" in low:
            issues.append("idempotency-key")
        if re.search(r"max.cost", low):
            issues.append("x-notorganic-max-cost-microusd")
        result["meteringHeaderIssues"] = issues
    if when:
        result["timestamp"] = when.isoformat().replace("+00:00", "Z")
    for key, value in {"httpStatus": status, "upstreamStatus": upstream, "errorCode": code, "state": state,
                       "app": safe_label(record.get("app", record.get("product"))),
                       "service": safe_label(record.get("service", record.get("serviceId"))),
                       "deploymentId": identifier(record.get("deploymentId")),
                       "requestId": identifier(record.get("requestId", record.get("request_id"))),
                       "idempotencyKey": identifier(record.get("idempotencyKey", record.get("idempotency_key"))),
                       "model": safe_label(record.get("model")), "provider": safe_label(record.get("provider")),
                       "billedMicros": integer(record.get("billedMicros")),
                       "reservedMicros": integer(record.get("reservedMicros", record.get("maxCostMicrousd")))}.items():
        if value is not None:
            result[key] = value
    return result


def parse_export(raw, source):
    events, notes = [], {"malformedJsonLines": 0, "oversizedLines": 0, "recordsCapped": False}

    def walk(value, pointer, inherited=None, depth=0):
        if depth > 12 or len(events) >= 10000:
            notes["recordsCapped"] = True
            return
        if isinstance(value, list):
            for index, item in enumerate(value):
                walk(item, f"{pointer}/{index}", inherited, depth+1)
        elif isinstance(value, dict):
            event = event_from(value, source, pointer, inherited, notes)
            if event:
                events.append(event)
            meta = {**(inherited or {}), **{k: value[k] for k in META_KEYS if k in value}}
            for key in WRAPPERS:
                if key in value:
                    walk(value[key], f"{pointer}/{key}", meta, depth+1)
        elif isinstance(value, str):
            if len(value.encode("utf-8")) > 65536:
                notes["oversizedLines"] += 1
                return
            try:
                decoded = json.loads(value)
            except ValueError:
                decoded = None
            if isinstance(decoded, (dict, list)):
                walk(decoded, pointer+"/json", inherited, depth+1)
            else:
                event = event_from({"message": value}, source, pointer, inherited, notes)
                if event:
                    events.append(event)

    text = raw.decode("utf-8", errors="replace")
    try:
        document = json.loads(text)
    except ValueError:
        document = None
    if isinstance(document, (list, dict)):
        walk(document, "json")
    else:
        for index, line in enumerate(text.splitlines()[:100000], 1):
            if len(line.encode("utf-8")) > 65536:
                notes["oversizedLines"] += 1
                continue
            line = re.sub(r"\x1b\[[0-9;]*m", "", line).strip()
            if not line:
                continue
            try:
                value = json.loads(line)
            except ValueError:
                if line.startswith(("{", "[")) and not line.startswith("[CONVEX"):
                    notes["malformedJsonLines"] += 1
                    continue
                value = line
            walk(value, f"line:{index}")
        if len(text.splitlines()) > 100000:
            notes["recordsCapped"] = True
    return events, notes


def ledger(events):
    groups, unbound = {}, 0
    for event in events:
        if event["stage"] not in ("reservation", "settlement") and "billedMicros" not in event:
            continue
        key = event.get("requestId")
        if not key:
            unbound += 1
            continue
        group = groups.setdefault(key, {"requestId": key, "states": set(), "charges": set(), "idempotencyKey": None})
        if event.get("state"):
            group["states"].add(event["state"])
        if "billedMicros" in event:
            group["charges"].add(event["billedMicros"])
        group["idempotencyKey"] = event.get("idempotencyKey") or group["idempotencyKey"]
    conflicts = [key for key, group in groups.items() if len(group["charges"] - {0}) > 1]
    known = [next(iter(group["charges"] - {0}), 0) for group in groups.values()]
    unresolved = sum(not g["charges"] for g in groups.values())
    retries = Counter(g["idempotencyKey"] for g in groups.values() if g["idempotencyKey"])
    return {"requestCount": len(groups), "releasedRequestCount": sum("released" in g["states"] for g in groups.values()),
            "chargedRequestCount": sum(x > 0 for x in known), "knownBilledMicros": None if conflicts else sum(known),
            "totalBilledMicros": None if conflicts or unresolved or unbound or not groups else sum(known), "unresolvedBillingRequestCount": unresolved,
            "conflictingChargeRequestIds": conflicts[:80], "conflictingChargeRequestCount": len(conflicts),
            "accountingDetailsTruncated": len(conflicts) > 80, "unboundAccountingEvents": unbound,
            "zeroChargeProvenRequestCount": sum(g["charges"] == {0} for g in groups.values()),
            "retryGroups": sum(count > 1 for count in retries.values()),
            "deduplication": "Accounting grouped by request ID; repeated exports do not multiply a charge. Zero absent billing is unknown, not proof of zero."}


def build_report(args, exports):
    all_events, sources, total = [], [], 0
    for index, (raw, origin) in enumerate(exports, 1):
        total += len(raw)
        if total > args.max_bytes:
            raise ValueError("input_byte_limit_exceeded")
        source = f"input-{index}"
        events, notes = parse_export(raw, source)
        sources.append({"source": source, "kind": origin, "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw), **notes})
        all_events.extend(events)
    unique = {}
    for event in all_events:
        content = {k: v for k, v in event.items() if k not in ("source", "record")}
        unique.setdefault(json.dumps(content, sort_keys=True), event)
    events = list(unique.values())
    scoped, excluded = [], 0
    for event in events:
        if (event.get("_appScope") and event["_appScope"] != scope_fingerprint(args.app)) or (event.get("_serviceScope") and event["_serviceScope"] != scope_fingerprint(args.service)):
            excluded += 1
            continue
        scoped.append(event)
    exact_indices = {i for i, e in enumerate(scoped) if args.ref in e["identifiers"]}
    exact = [e for i, e in enumerate(scoped) if i in exact_indices]
    index_by_id = defaultdict(list)
    for i, event in enumerate(scoped):
        for identifier_value in event["identifiers"]:
            index_by_id[identifier_value].append(i)
    linked_indices, seen_ids = set(exact_indices), set()
    pending_ids = deque(x for event in exact for x in event["identifiers"])
    # Only explicit shared identifiers connect executions. Timestamp proximity never does.
    # Each event/identifier is visited once within the bounded input.
    while pending_ids:
        identifier_value = pending_ids.popleft()
        if identifier_value in seen_ids:
            continue
        seen_ids.add(identifier_value)
        for i in index_by_id[identifier_value]:
            if i not in linked_indices:
                linked_indices.add(i)
                pending_ids.extend(scoped[i]["identifiers"])
    linked = [e for i, e in enumerate(scoped) if i in linked_indices]
    candidate_indices = [i for i, e in enumerate(scoped) if i not in linked_indices and e.get("timestamp") and args.start <= timestamp(e["timestamp"]) <= args.end]
    candidates = [scoped[i] for i in candidate_indices]
    reported = []
    for i in sorted(linked_indices) + candidate_indices:
        event = scoped[i]
        confidence = "exact_reference" if i in exact_indices else "linked_identifier" if i in linked_indices else "time_window_candidate"
        safe_event = {k: v for k, v in event.items() if not k.startswith("_")}
        reported.append({**safe_event, "confidence": confidence, "scopeKnown": "app" in event and "service" in event,
                         "inUtcWindow": bool(event.get("timestamp") and args.start <= timestamp(event["timestamp"]) <= args.end)})
    linked_in_window = [e for e in linked if e.get("timestamp") and args.start <= timestamp(e["timestamp"]) <= args.end]
    unknowns = ["Exact matching identifies an emitted ID, not automatically the first failure or its root cause.",
                "Client, relay, hosted action and telemetry may emit different IDs; absent exact match is not proof of no incident.",
                "A nearby event is a candidate until an explicit shared ID or independently verified request mapping connects it.",
                "Exported logs may omit upstream bodies, billing reconciliation or retained history."]
    if not exact:
        unknowns.append("Requested reference was not found in the supplied, bounded exports.")
    if any("timestamp" not in e for e in linked):
        unknowns.append("Some exact or linked events have no timezone-qualified timestamp.")
    if any(not e.get("app") or not e.get("service") for e in linked):
        unknowns.append("Some linked events lack explicit app/service scope; verify the export source.")
    if any(s["recordsCapped"] or s["malformedJsonLines"] or s["oversizedLines"] for s in sources):
        unknowns.append("Parsing was incomplete; malformed or bounded-away records prevent an all-clear.")
    result = {"schemaVersion": 1, "query": {"reference": args.ref, "app": args.app, "service": args.service,
               "startUtc": args.start.isoformat().replace("+00:00", "Z"), "endUtc": args.end.isoformat().replace("+00:00", "Z")},
              "sources": sources, "exactReferenceFound": bool(exact), "exactEventCount": len(exact),
              "linkedEventCount": len(linked), "timeWindowCandidateCount": len(candidates),
              "excludedOtherScopeCount": excluded, "duplicateEventCount": len(all_events)-len(events),
              "accounting": {"exactLinkedWindow": ledger(linked_in_window), "windowCandidates": ledger(candidates)},
