import { mutation, query } from "./_generated/server";
import { v } from "convex/values";
import {
  CHAT_SYNC_MAX_PAGE_BYTES, CHAT_SYNC_MAX_PAGE_RECORDS, ChatSyncIdSchema,
  ChatSyncIntegerSchema, ChatSyncWriteSchema, type ChatSyncRecord,
} from "../packages/contracts/src/chat-sync";
import { ProductIdSchema } from "../packages/contracts/src/catalog";
import { requireGatewaySecret } from "./lib";
import { requireLiveAccount } from "./accountDeletion";

const ownerArgs = { serviceSecret: v.string(), did: v.string(), product: v.string() };
const encrypted = v.union(v.null(), v.object({ key_id: v.string(), iv: v.string(), ciphertext: v.string() }));
function owner(did: string, product: string): string {
  if (!/^did:[a-z0-9]+:[A-Za-z0-9._:%-]{1,500}$/.test(did)) throw new Error("SYNC_INVALID_ACCOUNT");
  ProductIdSchema.parse(product);
  return JSON.stringify([did, product]);
}
function wire(row: { recordId: string; revision: number; sequence: number; mutationId: string; encrypted: ChatSyncRecord["encrypted"] }): ChatSyncRecord {
  return { id: row.recordId, revision: row.revision, sequence: row.sequence, mutation_id: row.mutationId, encrypted: row.encrypted };
}

export const list = query({
  args: { ...ownerArgs, after: v.number(), limit: v.number() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    await requireLiveAccount(ctx, args.did);
    const accountProduct = owner(args.did, args.product);
    ChatSyncIntegerSchema.parse(args.after);
    if (!Number.isInteger(args.limit) || args.limit < 1 || args.limit > CHAT_SYNC_MAX_PAGE_RECORDS) throw new Error("SYNC_INVALID_LIMIT");
