  previous_schema: z.nullable(z.string()),
  next_schema: z.nullable(z.string()),
});
export type SchemaDiff = z.infer<typeof schemaDiff>;

export const componentDiff = looseObject({
  diffType: componentDiffType,
  moduleDiff,
